245	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
246	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
247	        return Collections.unmodifiableList(sortedPets);
