261	     *
262	     * @param name to test
263	     * @return true if pet name is already in use
264	     */
265	    public Pet getPet(String name) {
266	        return getPet(name, false);
267	    }
268	
269	    /**
270	     * Return the Pet with the given name, or null if none found for this Owner.
271	     *
272	     * @param name to test
273	     * @return true if pet name is already in use
274	     */
275	    public Pet getPet(String name, boolean ignoreNew) {
276	        name = name.toLowerCase();
277	        for (Pet pet : getPetsInternal()) {
278	            if (!ignoreNew || !pet.isNew()) {
279	                String compName = pet.getName();
280	                compName = compName.toLowerCase();
281	                if (compName.equals(name)) {
282	                    return pet;
283	                }
284	            }
285	        }
286	        return null;
287	    }
288	
289	    public Pet getPet(Integer petId) {
290	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
291	    }
292	
293	    @Override
294	    public String toString() {
295	        return new ToStringCreator(this)
296	
297	            .append("id", this.getId())
298	            .append("new", this.isNew())
299	            .append("lastName", this.getLastName())
300	            .append("firstName", this.getFirstName())
301	            .append("address", this.address)
302	            .append("city", this.city)
303	            .append("telephone", this.telephone)
304	            .append("email", this.email)
305	            .toString();
306	    }
307	}
