12	
13	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
14	        Owner owner = ownerMapper.toOwner(request);
15	        LocalDate effective = owner.getRegistrationDate();
16	        if (effective == null) {
17	            effective = LocalDate.now();
18	        }
19	        // Roll the effective date (supplied or defaulted) onto a business day, so every
20	        // value derived from it — e.g. the membership number's year segment — matches.
21	        owner.setRegistrationDate(BusinessDay.adjust(effective));
22	        built.set(owner);
23	    }
24	}
